// === SNIPPET AUTOSUFICIENTE: PLANTAR PINO 3D CONICO PIRAMIDAL Y APUNTADO POR RAYCAST DE CURSOR ===
// Ejecutable desde el Editor UI de Snippets (apuntando con el ratón) o por código/F12.
(async function() {
  function resolveMat(matName) {
    if (typeof mc !== 'undefined' && mc.name2id && mc.name2id[matName]) return mc.name2id[matName];
    if (typeof mc !== 'undefined' && mc.blockKey) {
      var idx = mc.blockKey.indexOf('asset:assets/' + matName + '.vox.json');
      if (idx > 0) return idx;
    }
    return 1;
  }

  function getRaycastTarget() {
    if (typeof mcRaycast === 'function') {
      var hit = mcRaycast(30, true);
      if (hit && hit.cell) {
        var nx = hit.normal ? hit.normal[0] : 0;
        var ny = hit.normal ? hit.normal[1] : 0;
        var nz = hit.normal ? hit.normal[2] : 0;
        var tx = hit.cell[0] + nx;
        var ty = hit.cell[1] + (ny > 0 ? 1 : 0);
        var tz = hit.cell[2] + nz;
        return { x: tx, y: ty, z: tz };
      }
    }
    if (typeof mc !== 'undefined' && mc.pos) {
      return {
        x: Math.floor(Array.isArray(mc.pos) ? mc.pos[0] : mc.pos.x),
        y: Math.floor(Array.isArray(mc.pos) ? mc.pos[1] : mc.pos.y),
        z: Math.floor(Array.isArray(mc.pos) ? mc.pos[2] : mc.pos.z)
      };
    }
    return { x: 50, y: 15, z: 50 };
  }

  window.plantarPino = window.plantarPino || function(x, y, z, motivo, autor) {
    var target;
    if (x !== undefined && y !== undefined && z !== undefined) {
      target = { x: Math.floor(x), y: Math.floor(y), z: Math.floor(z) };
    } else {
      target = getRaycastTarget();
    }

    var px = target.x, py = target.y, pz = target.z;
    var reason = motivo || 'Plantado como hito en el mundo 3D';
    var agent = autor || 'Jugador';

    var logMat = resolveMat('tronco');
    var leafMat = resolveMat('hierba');

    // 1. TRONCO 3D (2 bloques verticales de altura)
    if (typeof setVoxel === 'function') {
      setVoxel(px, py, pz, logMat);
      setVoxel(px, py + 1, pz, logMat);
    }

    // 2. COPA INFERIOR ANCHA (Cuadrado 3x3 de 9 bloques de follaje en Y+2)
    if (typeof setVoxel === 'function') {
      for (var dx = -1; dx <= 1; dx++) {
        for (var dz = -1; dz <= 1; dz++) {
          setVoxel(px + dx, py + 2, pz + dz, leafMat);
        }
      }
    }

    // 3. COPA MEDIA (Cruz 3x3 de 5 bloques de follaje en Y+3)
    if (typeof setVoxel === 'function') {
      setVoxel(px, py + 3, pz, leafMat);
      setVoxel(px + 1, py + 3, pz, leafMat);
      setVoxel(px - 1, py + 3, pz, leafMat);
      setVoxel(px, py + 3, pz + 1, leafMat);
      setVoxel(px, py + 3, pz - 1, leafMat);
    }

    // 4. CIMA PIRAMIDAL (1 bloque de punta en Y+4)
    if (typeof setVoxel === 'function') {
      setVoxel(px, py + 4, pz, leafMat);
    }

    // 5. NOTA POST-IT 3D JUSTIFICATIVA
    var noteText = 'pino de emergencia\n' + agent + ': ' + reason;
    if (typeof mc !== 'undefined' && mc.notes) {
      mc.notes[px + ',' + py + ',' + pz] = noteText;
    }
    if (typeof toast === 'function') {
      toast('\u1F332 \u00A1' + agent + ': Plant\u00F3 un pino c\u00F3nico piramidal 3D en [' + px + ',' + py + ',' + pz + ']!');
    }
    console.log('[PLANTAR PINO] ' + agent + ' plant\u00F3 un pino c\u00F3nico piramidal 3D en [' + px + ',' + py + ',' + pz + ']: ' + reason);
  };

  // Si el usuario ejecuta este snippet desde el botón ▶️ "Ejecutar" del Editor UI:
  if (typeof mc !== 'undefined') {
    var targetPos = getRaycastTarget();
    var inputMotivo = prompt('\u1F332 Plantar Pino Piramidal 3D (Apuntando a [' + targetPos.x + ',' + targetPos.y + ',' + targetPos.z + '])\nEscribe la nota justificativa:', 'Pino plantado manualmente por el Jugador');
    if (inputMotivo !== null) {
      window.plantarPino(targetPos.x, targetPos.y, targetPos.z, inputMotivo, 'Jugador');
    }
  }
})();
